"""Επιμελημένα μαθήματα ελληνικών A2-C2 για το JUBA LISAN."""
from __future__ import annotations
from typing import Any

UNITS={
"A2":[("a2-unit-1","Σπίτι και γειτονιά","Χθες μετακόμισα σε ένα μικρό διαμέρισμα κοντά στο κέντρο.",["διαμέρισμα","γειτονιά","πολυκατοικία"]),
("a2-unit-2","Ταξίδια και μεταφορές","Το Σαββατοκύριακο θα ταξιδέψω με το τρένο.",["εισιτήριο","σταθμός","βαλίτσα"]),
("a2-unit-3","Υγεία και ευεξία","Πήγα στον γιατρό επειδή δεν ένιωθα καλά.",["γιατρός","φάρμακο","ραντεβού"]),
("a2-unit-4","Εργασία και ελεύθερος χρόνος","Μετά τη δουλειά συνήθως βλέπω μια ταινία ή κάνω μια βόλτα.",["συνάδελφος","ωράριο","χόμπι"])],
"B1":[("b1-unit-1","Εκπαίδευση και στόχοι","Θέλω να παρακολουθήσω ένα μάθημα για να βελτιώσω τις δεξιότητές μου.",["πτυχίο","στόχος","πρόοδος"]),
("b1-unit-2","Εργασία και επαγγελματική ζωή","Ο διευθυντής είπε ότι η ομάδα χρειάζεται περισσότερη συνεργασία.",["καριέρα","προσόν","προθεσμία"]),
("b1-unit-3","Μέσα και κοινωνία","Η είδηση προκάλεσε συζήτηση και πολλοί εξέφρασαν διαφορετικές απόψεις.",["είδηση","πηγή","κοινότητα"]),
("b1-unit-4","Σχέσεις και εμπειρίες","Μια δύσκολη εμπειρία μπορεί να μας βοηθήσει να αλλάξουμε.",["εμπιστοσύνη","διαφωνία","ανάμνηση"])],
"B2":[("b2-unit-1","Επιχειρηματολογία και συζήτηση","Παρόλο που η πρόταση έχει πλεονεκτήματα, χρειάζεται περισσότερα στοιχεία.",["επιχείρημα","αντίλογος","τεκμήριο"]),
("b2-unit-2","Πολιτισμός και ταυτότητα","Οι παραδόσεις αλλάζουν, χωρίς να χάνουν απαραίτητα τη σημασία τους.",["πολιτισμός","κληρονομιά","ταυτότητα"]),
("b2-unit-3","Οικονομία και επαγγελματική επικοινωνία","Η έκθεση παρουσιάζει τα βασικά οικονομικά δεδομένα με σαφή τρόπο.",["προϋπολογισμός","επένδυση","διαπραγμάτευση"]),
("b2-unit-4","Προβλήματα και λύσεις","Για να αντιμετωπιστεί το πρόβλημα, χρειάζεται ένα ρεαλιστικό σχέδιο.",["πρόβλημα","λύση","στρατηγική"])],
"C1":[("c1-unit-1","Ακαδημαϊκός λόγος","Τα διαθέσιμα δεδομένα δείχνουν ότι το φαινόμενο χρειάζεται περαιτέρω έρευνα.",["υπόθεση","δεδομένα","μεθοδολογία"]),
("c1-unit-2","Επαγγελματική επικοινωνία","Θα ήταν σκόπιμο να εξετάσουμε την πρόταση πριν λάβουμε οριστική απόφαση.",["σύσκεψη","πρόταση","σύσταση"]),
("c1-unit-3","Κοινωνική ανάλυση","Το φαινόμενο δεν μπορεί να εξηγηθεί από έναν μόνο παράγοντα.",["φαινόμενο","συσχέτιση","συνέπεια"]),
("c1-unit-4","Ρητορική και ύφος","Η επιλογή της διατύπωσης επηρεάζει τον τρόπο με τον οποίο γίνεται αντιληπτό το επιχείρημα.",["διατύπωση","έμφαση","ύφος"])],
"C2":[("c2-unit-1","Λεπτές σημασιολογικές αποχρώσεις","Η διαφορά ανάμεσα στις δύο εκφράσεις είναι κυρίως πραγματολογική.",["απόχρωση","υπόνοια","ιδιωματισμός"]),
("c2-unit-2","Σύνθετη επιχειρηματολογία","Το επιχείρημα φαίνεται πειστικό, αλλά η βασική του προϋπόθεση παραμένει αμφισβητήσιμη.",["προϋπόθεση","αντίλογος","συνεπαγωγή"]),
("c2-unit-3","Εξειδικευμένος και ακαδημαϊκός λόγος","Σε εξειδικευμένο πλαίσιο, ο όρος πρέπει να ορίζεται με απόλυτη ακρίβεια.",["ορολογία","πλαίσιο","ορισμός"]),
("c2-unit-4","Σύνθεση και δημιουργική έκφραση","Από τις διαθέσιμες πηγές μπορεί να εξαχθεί μόνο ένα περιορισμένο συμπέρασμα.",["σύνθεση","συμπέρασμα","περιορισμός"])]
}

def _unit(level,unit,title,example,words):
    vocab=[(w,f"λέξη σχετική με το θέμα «{title}»",f"Χρησιμοποιώ τη λέξη «{w}» σε σχετικό πλαίσιο.") for w in words]
    return {
      (level,unit,"grammar"):{"title":f"{title}: γραμματική","objective":f"Χρησιμοποίησε τη γραμματική της ενότητας «{title}» με ακρίβεια.","examples":[example]},
      (level,unit,"vocabulary"):{"title":f"{title}: λεξιλόγιο","objective":f"Ανάπτυξε λεξιλόγιο σχετικό με «{title}».","words":vocab},
      (level,unit,"reading"):{"title":f"{title}: ανάγνωση","objective":f"Κατανόησε ένα σύντομο κείμενο για «{title}».","text":f"{example} Το θέμα «{title}» παρουσιάζεται μέσα από καθημερινές, κοινωνικές ή επαγγελματικές καταστάσεις. Εντόπισε την κύρια ιδέα και τις σημαντικές λεπτομέρειες.","questions":["Ποια είναι η κύρια ιδέα του κειμένου;","Ποιες δύο λεπτομέρειες τη στηρίζουν;","Πώς θα εξηγούσες το κείμενο με δικά σου λόγια;"]},
      (level,unit,"listening"):{"title":f"{title}: ακρόαση","objective":f"Εντόπισε την κύρια ιδέα και βασικές λεπτομέρειες σε προφορικό λόγο.","transcript":f"{example} Ο ομιλητής εξηγεί την κατάσταση, αναφέρει έναν λόγο και δίνει ένα συγκεκριμένο παράδειγμα.","questions":["Ποια είναι η κύρια ιδέα;","Ποιον λόγο αναφέρει ο ομιλητής;","Ποιο παράδειγμα δίνει;"]},
      (level,unit,"speaking"):{"title":f"{title}: προφορική παραγωγή","objective":f"Μίλησε με σαφήνεια και συνοχή για «{title}».","prompt":f"Μίλησε για 1–2 λεπτά σχετικά με «{title}». Παρουσίασε άποψη, αιτιολόγηση και ένα συγκεκριμένο παράδειγμα.","phrases":["Κατά τη γνώμη μου","Από τη μία πλευρά","Για παράδειγμα","Επομένως"],"examples":[example]},
      (level,unit,"writing"):{"title":f"{title}: γραπτή παραγωγή","objective":f"Γράψε συνεκτικό κείμενο για «{title}».","prompt":f"Γράψε ένα κείμενο σχετικά με «{title}». Παρουσίασε την κύρια ιδέα, δύο σημεία ανάπτυξης και ένα συμπέρασμα.","guidance":["Χρησιμοποίησε τουλάχιστον τρεις λέξεις της ενότητας.","Σύνδεσε τις προτάσεις με κατάλληλους συνδέσμους.","Έλεγξε τη γραμματική και την ακρίβεια του λεξιλογίου."],"examples":[example]},
      (level,unit,"review"):{"title":f"{title}: επανάληψη","objective":f"Επανέλαβε γραμματική, λεξιλόγιο και επικοινωνιακές δεξιότητες.","questions":[f"Γράψε μία πρόταση σχετική με «{title}».","Χρησιμοποίησε τρεις νέες λέξεις σε δικές σου προτάσεις.","Σύνοψε την κύρια ιδέα σε δύο προτάσεις."]}
    }

S={}
for level,units in UNITS.items():
    for unit,title,example,words in units:S.update(_unit(level,unit,title,example,words))

def get_lesson_seed(level:str,unit_id:str,lesson_type:str)->dict[str,Any]|None:
    return S.get((str(level).upper(),str(unit_id),str(lesson_type).lower()))
